@@ -4347,17 +4347,69 @@ jobs:
       actions: write
       issues: write
       contents: read
+      # The linked-PR lookup (closedByPullRequestsReferences) needs this in
+      # private consumer repos; without it the lookup reads as unknown.
+      pull-requests: read
     steps:
       - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
         with:
           persist-credentials: false

+      # The retry budget lives in Workflows and is fetched at run time (manifest
+      # `runtime_fetched`), so every consumer applies the same bound.
+      - name: Checkout Workflows format retry budget
+        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
+        with:
+          repository: stranske/Workflows
+          sparse-checkout: |
+            .github/scripts/autopilot_format_retry_budget.js
+          sparse-checkout-cone-mode: false
+          path: workflows-lib
+          fetch-depth: 1
+          persist-credentials: false
+
+      # Decide before the backoff: a closed, disarmed, PR-linked or exhausted
+      # issue is settled at once instead of holding a runner for 30 minutes.
+      - name: Check format retry budget
+        id: budget
+        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9
+        env:
+          ISSUE_NUMBER: ${{ needs.auto-pilot.outputs.issue_number }}
+        with:
+          script: |
+            const issueNumber = parseInt(process.env.ISSUE_NUMBER, 10);
+            if (!issueNumber) {
+              core.setFailed('Missing issue number for format pause wakeup');
+              return;
+            }
+            const { createTokenAwareRetry } = require('./.github/scripts/github-api-with-retry.js');
+            const { runFormatWakeup } = require('./workflows-lib/.github/scripts/autopilot_format_retry_budget.js');
+            const { withRetry } = await createTokenAwareRetry({
+              github,
+              core,
+              env: process.env,
+              task: 'auto-pilot-format-pause-wakeup',
+              capabilities: ['issues:write', 'actions:write', 'contents:read'],
+            });
+            const decision = await runFormatWakeup({
+              withRetry,
+              core,
+              owner: context.repo.owner,
+              repo: context.repo.repo,
+              issueNumber,
+              dispatch: false,
+            });
+            core.setOutput('action', decision.action);
+            core.setOutput('retry', decision.action === 'retry' ? 'true' : 'false');
+
       - name: Bounded formatter pause backoff
+        if: steps.budget.outputs.retry == 'true'
         run: |
           echo "Waiting 30 minutes before automation-owned format retry..."
           sleep 1800

       - name: Clear pause and redispatch format step
+        if: steps.budget.outputs.retry == 'true'
         uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9
         env:
           ISSUE_NUMBER: ${{ needs.auto-pilot.outputs.issue_number }}
